solution.solution.cpp:
#include <cstddef>

const int* findValue(const int* begin, const int* end, int wanted)
{
    for (const int* p{ begin }; p != end; ++p)
        if (*p == wanted) return p;
    return end;
}

std::ptrdiff_t indexOf(const int* begin, const int* end, int wanted)
{
    const int* found{ findValue(begin, end, wanted) };
    return found == end ? -1 : found - begin;
}

const int* lowerBound(const int* begin, const int* end, int wanted)
{
    while (begin != end)
    {
        const int* middle{ begin + (end - begin) / 2 };
        if (*middle < wanted) begin = middle + 1;
        else end = middle;
    }
    return begin;
}

unitTests:
TEST("findValue") {
    const int a[]{ 7, 3, 9, 3, 1 };
    CHECK(findValue(a, a + 5, 3) == a + 1);
    CHECK(findValue(a, a + 5, 1) == a + 4);
    CHECK(findValue(a, a + 5, 42) == a + 5);
    CHECK(findValue(a + 2, a + 5, 3) == a + 3);
    CHECK(findValue(a, a, 7) == a);
}
TEST("indexOf") {
    const int a[]{ 7, 3, 9, 3, 1 };
    CHECK_EQ(indexOf(a, a + 5, 9), 2);
    CHECK_EQ(indexOf(a, a + 5, 42), -1);
    CHECK_EQ(indexOf(a + 2, a + 5, 3), 1);
}
TEST("lowerBound") {
    const int s[]{ 1, 3, 3, 5, 8, 13 };
    CHECK(lowerBound(s, s + 6, 3) == s + 1);
    CHECK(lowerBound(s, s + 6, 4) == s + 3);
    CHECK(lowerBound(s, s + 6, 0) == s);
    CHECK(lowerBound(s, s + 6, 13) == s + 5);
    CHECK(lowerBound(s, s + 6, 99) == s + 6);
    CHECK(lowerBound(s, s, 5) == s);
}
TEST("lowerBound on a large range") {
    static int big[100000];
    for (int i{ 0 }; i < 100000; ++i) big[i] = i * 2;
    CHECK(lowerBound(big, big + 100000, 77777) == big + 38889);
    CHECK(lowerBound(big, big + 100000, 0) == big);
}

